import os
import json
import base64
from typing import List, Dict, Any

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_image_bytes(image_path: str) -> bytes:
    with open(image_path, "rb") as f:
        return f.read()


def detect_labels(image_path: str, max_labels: int = 10, min_confidence: float = 50.0) -> List[Dict[str, Any]]:
    """
    Detect labels/objects in a static image using Amazon Rekognition.

    Requires AWS credentials configured via environment variables such as:
    AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_REGION
    """
    image_bytes = _load_image_bytes(image_path)
    rekognition = boto3.client("rekognition")

    try:
        response = rekognition.detect_labels(
            Image={"Bytes": image_bytes},
            MaxLabels=max_labels,
            MinConfidence=min_confidence,
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Rekognition label detection failed: {e}") from e

    labels = []
    for label in response.get("Labels", []):
        labels.append(
            {
                "name": label.get("Name"),
                "confidence": label.get("Confidence"),
                "instances": [
                    {
                        "bounding_box": instance.get("BoundingBox"),
                        "confidence": instance.get("Confidence"),
                    }
                    for instance in label.get("Instances", [])
                ],
                "parents": [parent.get("Name") for parent in label.get("Parents", [])],
            }
        )
    return labels


def detect_text(image_path: str, min_confidence: float = 50.0) -> List[Dict[str, Any]]:
    """
    Detect text in a static image using Amazon Rekognition.
    """
    image_bytes = _load_image_bytes(image_path)
    rekognition = boto3.client("rekognition")

    try:
        response = rekognition.detect_text(
            Image={"Bytes": image_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Rekognition text detection failed: {e}") from e

    detections = []
    for item in response.get("TextDetections", []):
        confidence = item.get("Confidence", 0.0)
        if confidence < min_confidence:
            continue
        detections.append(
            {
                "text": item.get("DetectedText"),
                "type": item.get("Type"),
                "confidence": confidence,
                "id": item.get("Id"),
                "parent_id": item.get("ParentId"),
                "geometry": item.get("Geometry"),
            }
        )
    return detections


def analyze_image(image_path: str, max_labels: int = 10, min_confidence: float = 50.0) -> Dict[str, Any]:
    return {
        "labels": detect_labels(image_path, max_labels=max_labels, min_confidence=min_confidence),
        "text": detect_text(image_path, min_confidence=min_confidence),
    }


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Detect labels and text in a static image using Amazon Rekognition.")
    parser.add_argument("image_path", help="Path to the input image")
    parser.add_argument("--max-labels", type=int, default=10, help="Maximum number of labels to return")
    parser.add_argument("--min-confidence", type=float, default=50.0, help="Minimum confidence threshold")
    args = parser.parse_args()

    result = analyze_image(args.image_path, max_labels=args.max_labels, min_confidence=args.min_confidence)
    print(json.dumps(result, indent=2, default=str))
